spec fn gap(a: i64, b: i64) -> bool { a + 1 < b }

spec fn strictly_between(a: i64, b: i64, r: i64) -> bool { a < r && r < b }

#[effects(pure)]
#[uses(gap, strictly_between)]
fn between(a: i64, b: i64) -> (r: i64)
    requires gap(a, b),
    ensures strictly_between(a, b, r),
{
    a
}

